const $=s=>document.querySelector(s);const palettes={electric:['#65edff','#aa86ff'],ember:['#ffad62','#ee6949'],ultraviolet:['#f681df','#9dacff']};const art=new Image();art.src='club.jpg';function text(c,s,cx,y,size,max,col){c.font=`${size}px Artist`;size*=Math.min(1,max/Math.max(1,c.measureText(s).width));c.font=`${size}px Artist`;c.fillStyle=col;c.textAlign='center';c.fillText(s,cx,y)}function draw(){if(!art.complete||!art.naturalWidth)return;const name=$('#artistName').value.trim()||'DEIN DJ-NAME',sound=$('#artistSound').value.trim()||'DEIN SOUND',a=palettes[$('#palette').value];for(const [id,kind] of [['bannerPreview','banner'],['mixPreview','mix'],['showPreview','show']]){const el=$('#'+id),c=el.getContext('2d'),w=el.width,h=el.height;const f=Math.max(w/art.width,h/art.height);c.drawImage(art,(w-art.width*f)/2,(h-art.height*f)/2,art.width*f,art.height*f);c.fillStyle='rgba(2,8,18,.52)';c.fillRect(0,0,w,h);const g=c.createLinearGradient(0,0,w,h);g.addColorStop(0,a[0]);g.addColorStop(1,a[1]);c.strokeStyle=g;c.lineWidth=3;c.beginPath();c.moveTo(w*.1,h*.15);c.lineTo(w*.22,h*.15);c.moveTo(w*.78,h*.85);c.lineTo(w*.9,h*.85);c.stroke();text(c,'NEONMIND / ARTIST LAUNCH',w*.5,h*.19,h*.023,w*.8,a[0]);text(c,name,w*.5,h*.47,kind==='show'?h*.09:h*.14,w*.83,'#f4f8ff');text(c,sound,w*.5,h*.55,h*.032,w*.81,a[0]);text(c,kind==='mix'?'MIDNIGHT SESSION':kind==='show'?'NIGHT FREQUENCY':'YOUR SOUND. YOUR NIGHT.',w*.5,h*.70,h*.045,w*.81,'#f4f8ff');text(c,'DEMO · DEIN NAME · DEIN LOOK',w*.5,h*.91,h*.019,w*.75,'#91a3bd')}}art.onload=draw;document.fonts.ready.then(draw);for(const id of ['artistName','artistSound'])$('#'+id).addEventListener('input',draw);$('#palette').addEventListener('change',()=>{document.querySelectorAll('.variant-image').forEach(im=>im.src=$('#palette').value+'/'+im.dataset.file);draw()});$('#personal').addEventListener('change',()=>$('#total').textContent=$('#personal').checked?'178,00 €':'79,00 €');$('#choose').addEventListener('click',()=>{let cart=[];try{cart=JSON.parse(localStorage.getItem('nm-cart')||'[]')}catch{}if(!Array.isArray(cart))cart=[];cart=cart.filter(x=>typeof x==='string'&&/^[a-z0-9-]{1,48}$/.test(x));cart.push('artist-launch');if($('#personal').checked)cart.push('artist-launch-personalisierung');else cart=cart.filter(x=>x!=='artist-launch-personalisierung');localStorage.setItem('nm-cart',JSON.stringify([...new Set(cart)]));location.href='/checkout'});